from dataclasses import replace
from DHI_v1.benchmark.plugin_task_loader import load_plugin_task
from DHI_v1.benchmark.plugin_execution import prepare_plugin_execution

base = load_plugin_task(
    "DHI_v1/benchmark/task_manifest.json",
    "DHI_v1/benchmark/fixtures/plugin_ecology/plugin_tool_registry.json",
    "ORBIT-A-S02-001",
)
# Tests the preparation/dispatch boundary only; this copy is not the live manifest.
plan = replace(base, model_runs_allowed=True)
schemas = {
    "mcp__TinyFish__search": {
        "type": "object", "properties": {"query": {"type": "string"}},
        "required": ["query"], "additionalProperties": False,
    },
    "mcp__TinyFish__fetch_content": {
        "type": "object", "properties": {"urls": {"type": "array", "items": {"type": "string"}}},
        "required": ["urls"], "additionalProperties": False,
    },
}
handlers = {
    tool_id: (lambda args: {"synthetic_handler": True, "received": args})
    for tool_id in plan.allowed_tool_ids
}
prepared = prepare_plugin_execution(plan, schemas=schemas, handlers=handlers)
result = prepared.dispatch(
    prepared.tool_name_by_id["mcp__TinyFish__search"],
    {"query": "synthetic dispatch smoke; no network"},
)
assert result["synthetic_handler"] is True
assert result["received"]["query"] == "synthetic dispatch smoke; no network"
print("prepared canonical tools:", sorted(prepared.tool_name_by_id))
print("synthetic dispatch: ok; external provider calls: 0")
